        case "word_tiles": correct = selectedWords == question.answerWords
        case "matching": correct = true
        default: correct = selected == question.answer
        }
        feedback = correct
        if !correct { recordMistake() }
    }
    private mutating func clearAnswer() {
        selected = nil; feedback = nil; selectedWords = []; matchedPairs = []
        selectedLeft = nil; selectedRight = nil; matchingMistake = false; pairNotice = nil
